// Compiles public/assets/scss/bootstrap-custom.scss (a trimmed Bootstrap
// entry point — see that file's own header comment for what's included and
// why) to public/assets/css/bootstrap-generated.css. Runs before esbuild's
// own CSS bundling (see esbuild.config.mjs) since esbuild bundles plain CSS
// via @import but doesn't compile Sass itself — this is a separate,
// synchronous pre-step so the generated file exists on disk before esbuild
// resolves site.css's own @import of it.
import * as sass from "sass";
import { writeFileSync, mkdirSync } from "fs";
import { dirname, join } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = join(__dirname, "..");

const entry = join(root, "public/assets/scss/bootstrap-custom.scss");
const outPath = join(root, "public/assets/css/bootstrap-generated.css");

const result = sass.compile(entry, {
	style: "expanded",
	quietDeps: true,
	loadPaths: [join(root, "node_modules")],
	// Bootstrap 5.2.3 predates Dart Sass's new @use/@forward module system —
	// its own @import-based partials are fine functionally, just noisy under
	// a modern sass compiler. Silenced rather than migrating vendor code
	// this project doesn't own.
	silenceDeprecations: ["import", "global-builtin", "color-functions", "abs-percent", "if-function"],
});

mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(
	outPath,
	"/* Generated by scripts/build-bootstrap.mjs from public/assets/scss/bootstrap-custom.scss — do not edit by hand. */\n" +
		result.css
);
console.log(`[build-bootstrap] compiled bootstrap-generated.css (${(result.css.length / 1024).toFixed(1)} KiB)`);
